    },
    {
      "id": "R2",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "일반 펀드의 낮은 환금성이라는 한계를 보완하는 상품으로 ETF가 실제 등장한다."
    },
    {
      "id": "R3",
      "type": "CAUSE",
      "otherName": "",
      "reason": "거래소에서 자유롭게 매매할 수 있는 구조가 높은 환금성을 만들어 낸다."
    },
    {
      "id": "R4",
      "type": "CAUSE",
      "otherName": "",
      "reason": "기초 지수를 추종하는 설계가 지수 구성 종목을 비율대로 보유하는 것과 유사한 경제적 효과를 낳는다."
    },
    {
      "id": "R5",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "ETF 한 주로 여러 종목을 보유한 것과 같은 효과를 얻는다는 사실이 소액 분산 투자가 가능하다는 판단을 뒷받침한다."
    },
    {
      "id": "R6",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "하루 한 번 산출되는 순자산가치로는 장중 거래에 대응하기 어렵다는 맥락에서 실시간 추정 지표가 보완 장치로 제공된다."
    },
    {
      "id": "R7",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "장 마감 후 하루 한 번만 산출되는 지표의 한계를 장중에 제공되는 실시간 추정 순자산가치가 보완한다."
    },
    {
      "id": "R8",
      "type": "CAUSE",
      "otherName": "",
      "reason": "투자자의 매수·매도 수요가 시장 가격을 형성하는 작용으로 인해 추정 자산 가치와의 괴리가 발생할 수 있다."
    },
    {
      "id": "R9",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "시장 가격과 실시간 추정 순자산가치의 차이를 장중 괴리율이라는 지표와 계산식으로 나타낸다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "괴리율의 계산 정의로부터 절댓값이 클수록 거래 가격과 자산 가치의 차이가 크다는 판단이 도출된다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자산 가치에서 크게 벗어난 가격으로 거래된다는 사실이 투자자의 비정상 가격 거래 위험이 커졌다는 판단을 뒷받침한다."
    },
    {
      "id": "R12",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "시장 가격과 자산 가치의 괴리라는 문제에 대해 유동성 공급자의 차익 거래가 이를 축소하는 대응으로 제시된다."
    },
    {
      "id": "R13",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "지속적인 매수·매도 호가 제시는 투자자의 원활한 ETF 거래를 돕기 위한 수단이다."
    },
    {
      "id": "R14",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "유동성 공급자가 참여하는 설정·환매 과정 중 설정의 구체적인 교환 절차를 풀어 설명한다."
    },
    {
      "id": "R15",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "유동성 공급자가 참여하는 설정·환매 과정 중 환매의 구체적인 교환 절차를 풀어 설명한다."
    },
    {
      "id": "R16",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "설정과 환매는 제공하는 자산과 지급받는 자산의 방향이 서로 반대인 절차로 비교된다."
    },
    {
      "id": "R17",
      "type": "CONDITION",
      "otherName": "",
      "reason": "괴리율이 양수인지 음수인지에 따라 설정 후 ETF 매도와 환매 후 기초 자산 매도로 거래 방식이 갈린다."
    },
    {
      "id": "R18",
      "type": "CAUSE",
      "otherName": "",
      "reason": "양의 괴리율에서 이루어지는 설정과 ETF 매도는 시장 가격을 본질 가치에 근접시키는 실제 가격 조정 작용을 한다."
    },
    {
      "id": "R19",
      "type": "CAUSE",
      "otherName": "",
      "reason": "음의 괴리율에서 이루어지는 ETF 매수와 환매 등의 차익 거래가 시장 가격을 본질 가치에 근접시키는 작용을 한다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "앞서 소개한 기초 지수 추종을 상관 계수 기준과 유형별 수익 목표로 더 자세히 설명한다."
    },
    {
      "id": "R21",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "상관 계수가 나타내는 유사성의 의미를 1에 가까운 값의 해석으로 구체화한다."
    },
    {
      "id": "R22",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "상관 계수를 0.9 이상으로 유지하는 설계는 기초 지수 수익률을 최대한 유사하게 구현하기 위한 수단이다."
    },
    {
      "id": "R23",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "전문가의 판단에 따른 종목 운용은 초과 수익이라는 목표를 이루기 위한 수단이다."
    },
    {
      "id": "R24",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "두 ETF 유형이 상관 계수 기준과 추구하는 수익 목표에서 서로 다른 특성을 보인다."
    },
    {
      "id": "R25",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "일별 수익률의 일정 배율을 목표로 하는 계약을 지수 변동 폭의 확대 추종을 위한 수단으로 활용한다."
    },
    {
      "id": "R26",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "변동 폭을 확대해 추종하는 동일한 구조에 손실 확대 위험도 따른다는 한계를 제시한다."
    },
    {
      "id": "R27",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "평가액을 다음 날 원금으로 삼는 계산 원리가 확대 배율 적용 시 지수가 회복되어도 원금은 회복되지 않는다는 설명의 근거가 된다."
    },
    {
      "id": "R28",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "지수는 회복되지만 투자금은 9,000원에 그치는 수치 사례가 레버리지형 ETF의 원금 미회복 위험을 구체적으로 보여 준다."
    },
    {
      "id": "R29",
      "type": "CAUSE",
      "otherName": "",
      "reason": "주가 상승 전에 권리를 판매한 행위가 이후 가격 상승에 따른 수익 실현을 실제로 제한한다."
    },
    {
      "id": "R30",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "대가를 받고 권리를 판매하는 전략은 주기적인 현금 수익을 확보하는 수단이다."
    },
    {
      "id": "R31",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 커버드콜형 ETF 안에서 상승 수익의 제한이라는 한계와 주기적 현금 수익이라는 장점을 함께 제시한다."
    },
    {
      "id": "R32",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "유형별 수익 목표와 운용 기준의 차이가 투자자가 수익률과 운용 방식 등을 종합적으로 고려해야 한다는 당위를 뒷받침한다."
    },
    {
      "id": "R33",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "특수한 수익 구조에 따른 손실 위험과 수익 제한이 상품 선택 시 유형별 위험을 종합적으로 고려해야 한다는 주장의 근거가 된다."
    }
  ]
}

